const listOf = n => { try { const raw = [].concat($(n).first().json.body ?? []);
  return (raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw).filter(x => x && x.id); } catch (e) { return []; } };

const list = listOf('Running experiments');
return list.length ? list.map(e => ({ json: { id: e.id, url: `${$env.CAMPAIGNS_URL}/experiments/${e.id}/decide` } }))
                   : [{ json: { url: `${$env.CAMPAIGNS_URL}/health`, noop: true } }];

function opsToItems(ops, base) {
  if (!ops.length) return [{ json: { method: 'GET', url: `${base}/health`, body: '{}', noop: true } }];
  return ops.map(o => ({ json: { ...o, body: JSON.stringify(o.body || {}) } }));
}

// A decided winner or no-difference result goes to the playbook (46): a winner starts a
// PROVISIONAL rule, a later same-direction winner marks it replicated (a person then approves
// it in form 51), a contradiction demotes or retires it. Inconclusive changes nothing.
const asked = $('One per experiment').all().map(i => i.json);
const ops = [];
$input.all().forEach((r, i) => {
  const b = r.json.body || {};
  if (asked[i].noop || r.json.statusCode !== 200 || b.status !== 'decided') return;
  if (!['winner', 'no_practical_difference'].includes(b.decision)) return;
  const e = b.experiment || {};
  ops.push({ method: 'POST', url: `${$env.LEARNING_URL}/rules/from-experiment`, experiment_id: e.id, body: {
    experiment_id: e.id, decision: b.decision, variable: e.variable, channels: e.channels,
    values: (e.arms || []).map(a => a.value), winner: b.winner_value || null, loser: b.loser_value || null,
    lift_hdi: b.lift_hdi, decided_at: e.decided_at, summary: b.summary || null } });
});
return opsToItems(ops, $env.LEARNING_URL);

const asked = $('One per experiment').all().map(i => i.json);
const decided = $('Decide').all().map(i => i.json);
const ruleOps = $('Rule ops').all().map(i => i.json);
const ruleRes = $input.all().map(i => i.json);
const rules = {};
ruleRes.forEach((r, i) => { if (!ruleOps[i].noop) rules[ruleOps[i].experiment_id] = r.statusCode === 200 ? r.body : { error: r.statusCode }; });
const lines = [], out = [];
decided.forEach((r, i) => {
  const a = asked[i];
  if (a.noop) return;
  const b = r.body || {};
  if (r.statusCode === 409) { out.push({ id: a.id, decision: 'not_due' });
    lines.push(`- #${a.id}: no look due (next ${((b.detail || {}).next_look_at || '?').slice(0, 10)})`); return; }
  if (r.statusCode !== 200) { out.push({ id: a.id, error: r.statusCode });
    lines.push(`- #${a.id}: could not be analysed (${r.statusCode}: ${JSON.stringify(b.detail ?? b).slice(0, 120)})`); return; }
  out.push({ id: a.id, look: b.look, decision: b.decision, lift_hdi: b.lift_hdi, rule: rules[a.id] || null });
  let line = `- #${a.id} look ${b.look}: ${b.summary}`;
  const rr = rules[a.id];
  if (rr && rr.action) {
    const act = { created: 'new PROVISIONAL rule (writers do not see it until a later experiment agrees and you approve it)',
      replicated: `rule replicated: approve it in the rules form ${String($env.N8N_PUBLIC_URL || 'http://localhost:5678/').trim().replace(/\/?$/, '/')}form/mkt-rules-review`,
      confirmed: 'active rule confirmed again', demoted: 'active rule DEMOTED to provisional', retired: 'rule retired',
      contradicted: 'rule contradicted', counted: 'counted (rule was rejected)', already_counted: 'already counted', none: 'no rule' }[rr.action] || rr.action;
    line += ` → ${act}${rr.rule ? ` (#${rr.rule.id} "${rr.rule.text}")` : ''}`;
  } else if (rr && rr.error) line += ` → playbook update failed (${rr.error})`;
  lines.push(line);
});
const text = lines.length ? `*Experiments, weekly look*\n${lines.join('\n')}` : '*Experiments, weekly look*: none running.';
return [{ json: { text, results: out } }];

function notifyRequest(text, env, waits) {
  const fmt = String(env.NOTIFY_FORMAT || 'generic').trim().toLowerCase();
  const telegram = fmt === 'telegram';
  if (telegram ? !(env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID) : !env.NOTIFY_WEBHOOK_URL) return null;
  const plain = String(text ?? '');
  const form = `${String(env.N8N_PUBLIC_URL || 'http://localhost:5678/').trim().replace(/\/?$/, '/')}form/mkt-content-approval`;
  const link = waits && !plain.includes(form) ? form : null;   // already in the text: once is enough
  // Cut the text (never the link) to the longest prefix whose rendered message fits:
  // escaping can make the rendered text several times longer, so search for it.
  const fit = (render, max) => {
    if (render(plain).length <= max) return render(plain);
    let lo = 0, hi = plain.length;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (render(plain.slice(0, mid).trimEnd() + '…').length <= max) lo = mid; else hi = mid - 1;
    }
    return render(plain.slice(0, lo).trimEnd() + '…');
  };
  const mdLink = /\[([^\]\n]+)\]\((https?:\/\/[^\s)"<>]+)\)/g;
  const oneStar = /(^|[^*\w])\*(?![\s*])([^*\n]*?[^\s*])\*(?![*\w])/g;   // Slack-style *bold*
  const heading = /^#{1,6}[ \t]+(.+)$/gm;
  if (telegram) {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<a href="$2">$1</a>')
      .replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>').replace(oneStar, '$1<b>$2</b>').replace(heading, '<b>$1</b>')
      + (link ? `\n\n<a href="${esc(link)}">Open the approval form</a>` : '');
    const api = String(env.TELEGRAM_API_URL || 'https://api.telegram.org').trim().replace(/\/+$/, '');
    return { format: 'telegram', url: `${api}/bot<TELEGRAM_BOT_TOKEN>/sendMessage`, body: {
      chat_id: String(env.TELEGRAM_CHAT_ID).trim(), text: fit(render, 4096), parse_mode: 'HTML',
      disable_web_page_preview: true } };
  }
  const url = '<NOTIFY_WEBHOOK_URL>';
  if (fmt === 'slack') {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<$2|$1>').replace(/\*\*([^*\n]+)\*\*/g, '*$1*').replace(heading, '*$1*')
      + (link ? `\n\n<${link}|Open the approval form>` : '');
    return { format: 'slack', url, body: { text: fit(render, 40000) } };
  }
  if (fmt === 'discord') {
    // <url> stops link previews; Discord bold is **x**; nothing in the text can ping anyone.
    const render = t => t.replace(oneStar, '$1**$2**').replace(/(^|\s)(https?:\/\/[^\s<>]+)/g, '$1<$2>')
      + (link ? `\n\nApproval form: <${link}>` : '');
    return { format: 'discord', url, body: { content: fit(render, 2000), allowed_mentions: { parse: [] } } };
  }
  const t = link ? `${plain.trimEnd()}\n\nApproval form: ${link}` : plain;
  return { format: 'generic', url, body: { text: t, content: t } };   // the payload before NOTIFY_FORMAT
}

return $input.all().flatMap(item => {
  const req = notifyRequest(item.json.text, $env, false);
  return req ? [{ json: req }] : [];
});
